requiredSamples.queryHandler:
public class GetUomLookupByItem
{
    public record Query(Guid ItemId) : IQuery<List<LookupDto>>;

    public class QueryHandler(IAppDbContext context) : IQueryHandler<Query, List<LookupDto>>
    {
        public async Task<List<LookupDto>> HandleAsync(Query query, CancellationToken ct = default)
        {
            var item = await context.Items.AsNoTracking()
                .Where(x => x.Id == query.ItemId)
                .Select(x => new { x.DefaultUom })
                .FirstOrDefaultAsync(ct);

            if (item?.DefaultUom is null) return [];

            var defaultUom = await context.Uoms.AsNoTracking()
                .Where(x => x.Code == item.DefaultUom)
                .Select(x => new { x.Id, x.Code, x.Name })
                .FirstOrDefaultAsync(ct);

            if (defaultUom is null) return [];

            var convertibleUomIds = await context.UomConversions.AsNoTracking()
                .Where(x => x.FromUomId == defaultUom.Id || x.ToUomId == defaultUom.Id)
                .Select(x => x.FromUomId == defaultUom.Id ? x.ToUomId : x.FromUomId)
                .Distinct()
                .ToListAsync(ct);

            var allUomIds = convertibleUomIds.Prepend(defaultUom.Id).Distinct().ToList();

            return await context.Uoms.AsNoTracking()
                .Where(x => allUomIds.Contains(x.Id))
                .OrderBy(x => x.Name)
                .Select(x => new LookupDto(x.Id, x.Code, x.Name))
                .ToListAsync(ct);
        }
    }
}

